<style>
.lv-op-card{background:#fff;border:1px solid #e8e3d8;border-radius:18px;padding:22px;min-width:0;box-shadow:0 3px 16px #30291704}.lv-op-card h1{font-size:24px;font-weight:750;line-height:1.25}.lv-op-card h2{font-size:17px;font-weight:720;margin:0 0 12px}.lv-op-card h3{font-size:14px;font-weight:700}.lv-op-card p{line-height:1.65;margin:10px 0}.lv-op-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.lv-record-pane{display:grid;gap:18px;min-width:0;animation:lv-pane-in .2s ease-out}.lv-op-heading,.lv-record-top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.lv-record-top{font-size:12px}.lv-record-subtle{font-size:12px;color:#7b776b}.lv-record-location{font-size:13px;font-weight:600}.lv-record-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.lv-record-hero{display:flex;align-items:center;gap:18px;min-width:0}.lv-record-hero>div{min-width:0;overflow-wrap:anywhere}.lv-record-hero>img{height:90px;width:90px;object-fit:cover;border-radius:14px;flex-shrink:0}.lv-record-hero p{font-size:12px;color:#777267;margin:6px 0}.lv-item-badge{display:inline-block;border-radius:7px;padding:4px 8px;font-size:10px;letter-spacing:.2px;background:#f3ecd9;color:#7c6026;font-weight:700}.lv-op-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.lv-op-actions .fi-btn{font-size:12px;min-height:40px}.lv-record-link{display:block;color:#8b6b2b;font-weight:650;font-size:12px;margin:14px 0;overflow-wrap:anywhere}.lv-text-button{display:block;font-size:11px;color:#8b6b2b;text-decoration:underline;text-underline-offset:3px;min-height:34px}.lv-record-tabs{display:flex;gap:5px;padding:5px;background:#ede9df;border-radius:13px;max-width:500px}.lv-record-tabs button{flex:1;min-height:43px;padding:8px 12px;border-radius:9px;font-size:12px;font-weight:700;transition:background .16s,box-shadow .16s}.lv-record-tabs button.is-active{background:#fff;box-shadow:0 2px 5px #3129130b;color:#8a6a2d}.lv-key-values{margin:0}.lv-key-values>div{display:flex;justify-content:space-between;gap:14px;border-bottom:1px solid #f0ece3;padding:12px 0;font-size:12px}.lv-key-values dt{color:#807b6d}.lv-key-values dd{font-weight:700;text-align:right;overflow-wrap:anywhere;max-width:65%}.lv-key-values>div:last-child{border-bottom:0}.lv-money-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.lv-money{display:flex;flex-direction:column;gap:9px;padding:18px}.lv-money>span{font-size:11px;color:#8a806a}.lv-money strong{font-size:23px;font-weight:750;overflow-wrap:anywhere}.lv-money small{font-size:16px;color:#93876b}.lv-decision-card{background:#f8f5ed;border-color:#ded1ad}.lv-decision-card h2{margin-top:12px}.lv-decision-card>p{font-size:13px}.lv-entry-row{display:flex;justify-content:space-between;gap:15px;padding:15px 0;border-bottom:1px solid #ede9e0;font-size:12px}.lv-entry-row>div{min-width:0}.lv-entry-row>div:last-child{text-align:right;flex-shrink:0;max-width:42%}.lv-entry-row small,.lv-share-row small,.lv-timeline-entry small{display:block;font-size:10px;color:#8c8373;margin:4px 0}.lv-entry-row p{margin:5px 0;overflow-wrap:anywhere}.lv-entry-row.is-void{opacity:.6}.lv-entry-row .lv-text-button{margin-left:auto}.lv-timeline-entry{padding:16px 0 16px 15px;border-left:2px solid #e7d9b8;border-bottom:1px solid #f0ede5}.lv-timeline-entry strong{font-size:12px}.lv-evidence-links{display:flex;flex-wrap:wrap;gap:8px}.lv-evidence-links a{font-size:10px;border:1px solid #e3d7bb;border-radius:8px;padding:8px;color:#846624}.lv-sharing-controls{margin-top:24px;border-top:1px solid #e9e4d9;padding-top:20px}.lv-share-row{padding:13px 0;border-bottom:1px solid #eee9dd;font-size:12px}.lv-record-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.lv-record-gallery img{aspect-ratio:1;object-fit:cover;width:100%;border-radius:12px}.lv-scan-layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:20px;align-items:start}.lv-scan-layout .lv-camera{aspect-ratio:1.5;min-height:0}.lv-scan-result{position:sticky;top:90px}.lv-scan-result>.lv-pill{margin-bottom:16px}.lv-code-search{margin-top:20px;padding-top:18px;border-top:1px solid #ebe5d8}.lv-code-search label{font-size:12px;font-weight:650;display:block;margin-bottom:8px}.lv-code-search>div{display:flex;gap:8px}.lv-code-search input{min-width:0;width:100%;font-size:16px;border:1px solid #d5ccb9;padding:11px 12px;border-radius:10px}.lv-code-search button{flex-shrink:0;font-size:12px}.lv-match-row{display:flex;width:100%;align-items:center;justify-content:space-between;gap:10px;padding:14px 0;border-bottom:1px solid #eae5d9;text-align:left;font-size:13px;transition:background .15s}.lv-match-row:hover{background:#faf7ef}.lv-match-row small{display:block;font-size:10px;color:#817967;margin-top:5px}.lv-scan-tools{display:flex;align-items:center;flex-wrap:wrap;gap:14px;margin:14px 0}.lv-scan-tools label{font-size:12px;display:flex;align-items:center;gap:8px}.lv-scan-tools input{max-width:160px;accent-color:#9c7b34}.lv-error{color:#b91c1c;font-size:12px}.lv-new-piece{animation:lv-pane-in .2s ease-out}.lv-new-piece>.lv-op-heading{margin-bottom:15px}
